def evaluate(current_reputation, observation, my_history, round_num):
    """
    Update reputation based on observed action.
    Increase reputation on cooperation, decrease on defection,
    with a learning rate that makes the reputation slowly adapt.
    """
    learning_rate = 0.2
    if observation['action'] == 'cooperate':
        update = learning_rate * (1.0 - current_reputation)
    else:
        update = learning_rate * (-1.0 - current_reputation)
    new_rep = current_reputation + update
    return max(-1.0, min(1.0, new_rep))

def decide(recipient_reputation, round_num, my_history):
    """
    Cooperate only if the recipient's reputation is sufficiently high.
    The threshold increases over rounds to become more selective,
    but does not use any information about past partner actions.
    """
    if round_num < 20:
        threshold = 0.0           # generous early on
    elif round_num < 50:
        threshold = 0.2
    else:
        threshold = 0.4           # strict later
    return recipient_reputation >= threshold
